      "fluxograma_decisao": "<div style='display:flex;flex-direction:column;align-items:center;gap:8px;padding:20px;background:#0f172a;border-radius:18px;border:1px solid #334155;'><div style='background:linear-gradient(135deg,#4f46e5,#6366f1);color:#f8fafc;border:none;padding:14px 22px;border-radius:12px;font-weight:600;text-align:center;max-width:480px;width:100%;line-height:1.6;'>1. Analisar questão sobre Sociologia Ambiental e Questões Contemporâneas</div><div style='font-size:1.3em;color:#818cf8;font-weight:bold;line-height:1;'>⬇</div><div style='background:#1e293b;color:#f8fafc;border:1px solid #6366f1;padding:14px 22px;border-radius:12px;font-weight:600;text-align:center;max-width:480px;width:100%;line-height:1.6;'>2. Identificar dados fornecidos</div><div style='font-size:1.3em;color:#818cf8;font-weight:bold;line-height:1;'>⬇</div><div style='background:#1e293b;color:#f8fafc;border:1px solid #6366f1;padding:14px 22px;border-radius:12px;font-weight:600;text-align:center;max-width:480px;width:100%;line-height:1.6;'>3. Aplicar regra de SOCIOLOGIA</div><div style='font-size:1.3em;color:#818cf8;font-weight:bold;line-height:1;'>⬇</div><div style='background:linear-gradient(135deg,#059669,#10b981);color:#f8fafc;border:none;padding:14px 22px;border-radius:12px;font-weight:600;text-align:center;max-width:480px;width:100%;line-height:1.6;'>4. Validar resultado final</div></div>",
